Find the area of this rectangle in simplest form.
[tikz]
\begin{tikzpicture}
\coordinate (A) at (0,0);
\coordinate (B) at (3.9,0);
\coordinate (C) at (3.9,2.6);
\coordinate (D) at (0,2.6);
\draw (A) -- (B) node[midway,below] {$\sqrt{27}\text{ cm}$};
\draw (B) -- (C);
\draw (C) -- (D);
\draw (D) -- (A) node[midway,left] {$\sqrt{12}\text{ cm}$};
\end{tikzpicture}
[/tikz]

Find the perimeter of this rectangle in simplest form.
[tikz]
\begin{tikzpicture}
\coordinate (A) at (0,0);
\coordinate (B) at (2.68,0);
\coordinate (C) at (2.68,4.02);
\coordinate (D) at (0,4.02);
\draw (A) -- (B) node[midway,below] {$2\sqrt{5}\text{ cm}$};
\draw (B) -- (C);
\draw (C) -- (D);
\draw (D) -- (A) node[midway,left] {$\sqrt{45}\text{ cm}$};
\end{tikzpicture}
[/tikz]
